import assert from 'node:assert/strict';import fs from 'node:fs/promises';import path from 'node:path';
import {loadEnv,preflight} from '../lib/env.mjs';import {createSession} from '../lib/harness.mjs';
const env=await loadEnv();assert.ok(['localhost','127.0.0.1'].includes(new URL(env.baseUrl).hostname));await preflight(env);
const phase=process.env.QA_QUOTATION_ZERO_PHASE;const output=path.resolve(process.env.QA_QUOTATION_ZERO_OUTPUT_DIR||'qa/2026-10-01_comprehensive-audit_ui35-zero-material-final');await fs.mkdir(output,{recursive:true});
const originalProof=JSON.parse(await fs.readFile('qa/2026-10-01_comprehensive-audit_ui29-final/driver-assertions.json','utf8'));const original=originalProof.persisted.detail.body;assert.equal(original.id,45);const key='1:1.25T';const originalCell=original.cells.find(c=>`${c.routeId}:${c.vehicleSizeClassCode}`===key);assert.equal(originalCell.heSo,1);const target=0;
const ctx=await createSession({env,role:'ADMIN',evidenceDir:output,runId:'UI35-ZERO'});const statePath=path.join(output,'transaction-state.json');let transaction=await fs.readFile(statePath,'utf8').then(JSON.parse).catch(e=>{if(e.code==='ENOENT')return{phase:'initial'};throw e;});const proof={role:ctx.role,account:ctx.username,quotationId:45,originalKey:key,originalCoefficient:1,targetCoefficient:target,states:[],writes:[],httpErrors:[]};let permit=null;
const clean=c=>({routeId:c.routeId,vehicleSizeClassCode:c.vehicleSizeClassCode,heSo:c.heSo});const originalCells=original.cells.map(clean);const save=async()=>{const value=JSON.stringify({...proof,transaction,errors:ctx.errors},null,2)+'\n';await fs.writeFile(path.join(output,'driver-assertions.json'),value);if(phase)await fs.writeFile(path.join(output,`driver-${phase}-assertions.json`),value);};
async function reads(){const detail=await ctx.apiGet('/quotations/45'),versions=await ctx.apiGet('/quotations/45/versions');assert.equal(detail.status,200);assert.equal(versions.status,200);return{detail,versions};}
async function capture(label){const shot=await ctx.screenshot(label);const dom=await ctx.page.evaluate(()=>({url:location.pathname,text:document.body.innerText,selected:document.querySelector('.quotation-frames .is-selected')?.innerText,inputs:[...document.querySelectorAll('.quotation-route-block input')].map(e=>({label:e.getAttribute('aria-label'),value:e.value})),focus:document.activeElement?.outerHTML?.slice(0,350)}));const domPath=shot.replace(/\.png$/,'-dom.json');await fs.writeFile(domPath,JSON.stringify(dom,null,2)+'\n');proof.states.push({label,shot,domPath,dom});await save();}
async function open(){await ctx.page.setViewport({width:390,height:900,hasTouch:true});await ctx.goto('/config/quotations');const h=await ctx.page.evaluateHandle(name=>[...document.querySelectorAll('.quotation-frames tbody tr')].find(e=>e.textContent.includes(name)),original.templateName);const row=h.asElement();assert.ok(row);await row.click();await ctx.settle(300);await ctx.page.keyboard.press('Space');await ctx.settle(150);assert.equal(await row.evaluate(e=>document.activeElement===e),true);await ctx.page.keyboard.press('Enter');await ctx.page.waitForSelector('.quotation-route-block input');await capture('selected-space-enter');}
async function inputValue(value,label){const input=await ctx.page.$('[aria-label="Hệ số Hải Phòng-NEWEB 1.25T"]');assert.ok(input);await input.click();const length=await input.evaluate(e=>e.value.length);for(let i=0;i<length;i++)await ctx.page.keyboard.press('ArrowRight');for(let i=0;i<length;i++)await ctx.page.keyboard.press('Backspace');assert.equal(await input.evaluate(e=>e.value),'','Native selection cleared existing coefficient');await ctx.page.keyboard.type(String(value));assert.equal(await input.evaluate(e=>e.value),String(value),'Exact intended coefficient draft');await capture(label);await ctx.page.keyboard.press('Tab');}
try{
 await ctx.page.setCacheEnabled(false);await ctx.page.setRequestInterception(true);ctx.page.on('request',r=>{if(!['POST','PUT','PATCH','DELETE'].includes(r.method())){void r.continue();return;}const body=JSON.parse(r.postData()||'{}');const desired=originalCells.map(c=>`${c.routeId}:${c.vehicleSizeClassCode}`===key?{...c,heSo:permit}:c);const allowed=permit!==null&&r.method()==='PUT'&&new URL(r.url()).pathname==='/api/quotations/45'&&JSON.stringify(body.cells)===JSON.stringify(desired)&&JSON.stringify(body.fees)===JSON.stringify(original.fees)&&body.templateName===original.templateName&&body.effectiveDate===original.effectiveDate&&body.surchargeRoundingMode===original.surchargeRoundingMode&&body.note===original.note;proof.writes.push({method:r.method(),url:r.url(),body,permitted:allowed,idempotencyKeyPresent:Boolean(r.headers()['idempotency-key'])});permit=null;void(allowed?r.continue():r.abort('blockedbyclient'));});ctx.page.on('response',r=>{if(r.status()>=400)proof.httpErrors.push({url:r.url(),status:r.status()});});
 const initial=await reads();proof.initial=initial;await open();
  if(transaction.phase==='initial'){assert.equal(initial.versions.body.items[0].version,3,'Unknown prior mutation; refuse duplicate');assert.deepEqual(initial.detail.body.cells.map(clean),originalCells);const input=await ctx.page.$('[aria-label="Hệ số Hải Phòng-NEWEB 1.25T"]');assert.ok(input);await input.click();const length=await input.evaluate(e=>e.value.length);for(let i=0;i<length;i++)await ctx.page.keyboard.press('ArrowRight');for(let i=0;i<length;i++)await ctx.page.keyboard.press('Backspace');await capture('blank-draft-no-save');await ctx.page.keyboard.press('Tab');await ctx.settle(300);assert.equal(proof.writes.length,0,'Blank emits no material attempt');assert.equal(await input.evaluate(e=>e.value),'1','Blank blur restores persisted coefficient');assert.deepEqual(await reads(),initial);await capture('blank-blurred-no-save');permit=target;const responsePromise=ctx.page.waitForResponse(r=>r.request().method()==='PUT'&&new URL(r.url()).pathname==='/api/quotations/45');responsePromise.catch(()=>{});await inputValue(target,'valid-coefficient-change-ready');const response=await responsePromise;assert.equal(response.status(),200);transaction={phase:'changed',changedResponseStatus:200,originalCells};await fs.writeFile(statePath,JSON.stringify(transaction,null,2)+'\n');await ctx.settle(350);const changed=await reads();assert.equal(changed.detail.body.cells.length,30);assert.equal(new Set(changed.detail.body.cells.map(c=>c.routeId)).size,3);assert.deepEqual(changed.detail.body.cells.map(clean),originalCells.map(c=>`${c.routeId}:${c.vehicleSizeClassCode}`===key?{...c,heSo:target}:c));assert.deepEqual(changed.detail.body.fees,original.fees);assert.equal(changed.versions.body.items[0].version,4);proof.changed=changed;await capture('changed-persisted-full-30');}
  if(transaction.phase==='changed'&&phase!=='change'){await open();const changed=await reads();assert.equal(changed.detail.body.cells.find(c=>`${c.routeId}:${c.vehicleSizeClassCode}`===key).heSo,target);permit=1;const responsePromise=ctx.page.waitForResponse(r=>r.request().method()==='PUT'&&new URL(r.url()).pathname==='/api/quotations/45');responsePromise.catch(()=>{});await inputValue(1,'forward-restore-ready');const response=await responsePromise;assert.equal(response.status(),200);transaction={...transaction,phase:'restored',restoreResponseStatus:200};await fs.writeFile(statePath,JSON.stringify(transaction,null,2)+'\n');await ctx.settle(350);}
  if(phase==='change'){assert.equal(transaction.phase,'changed');assert.equal(proof.writes.length,1);assert.equal(ctx.errors.length,0);proof.changedPhaseComplete=true;await save();console.log(JSON.stringify({changedPhaseComplete:true,quotationId:45,version:4,cells:30,routes:3,actualWrites:1}));}else{
  const restored=await reads();assert.deepEqual(restored.detail.body.cells.map(clean),originalCells);assert.deepEqual(restored.detail.body.fees,original.fees);assert.equal(restored.versions.body.items[0].version,5);assert.equal(restored.versions.body.items.length,5);proof.restored=restored;await capture('restored-full-30-version-5');assert.equal(proof.writes.filter(w=>!w.permitted).length,0);assert.ok(proof.writes.length<=2);assert.ok(proof.writes.every(w=>w.idempotencyKeyPresent));assert.equal(ctx.errors.length,0);assert.equal(proof.httpErrors.length,0);proof.complete=true;await save();console.log(JSON.stringify({complete:true,quotationId:45,version:5,restoredCells:30,routes:3,actualWrites:proof.writes.length}));
  }
}catch(error){proof.failure=error.stack;await save();throw error;}finally{await save();await ctx.browser.close();}
